insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('SC', 'default', 'Seychelles reference chart of accounts', '{}'::jsonb, true, 'companies', array['SC-IFRS-IS', 'SC-IFRS-SFP']::text[], null, 'There is no legal chart of accounts in the texts read for Seychelles, and no text prescribing a financial reporting framework was found (see the README). This chart is original: four digits, blocked so that each range reaches one line of the IFRS-style statements below (IAS 1, expenses by nature), with the accounts a Seychelles trading company keeps — VAT output and input tax, import VAT owed to the Seychelles Revenue Commission at the border, Income and Non-Monetary Benefits Tax withheld, social security contributions, and the Tourism Marketing Tax.', 'ias-1')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
