insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('SC', 'SC-P-0', 'Purchase, exempt or zero-rated, no input tax', '{}'::jsonb, 'A purchase that carries no VAT: an exempt supply received, or a zero-rated one', 'percent', 0, 'purchase', 'exempt', date '2014-01-20', null, 'VAT Act, First Schedule Part II and Second Schedule as substituted by S.I. 4 of 2014 — a supplier of an exempt or zero-rated supply charges no VAT, so the buyer has no input tax. The return has no line for these purchases, so the code posts to no box.', 'E', null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-schedules', null, null, null, null),
  ('SC', 'SC-P-15', 'Purchase, standard rate 15 %, deductible', '{}'::jsonb, 'A local purchase of goods or services at the standard rate, used to make taxable supplies', 'percent', 15, 'purchase', 'domestic', date '2014-01-20', null, 'VAT return, line 5.2 — Input tax allowed as a credit on goods and services purchased locally: the instructions ask for the cost exclusive of VAT in box 5.2A and the VAT incurred in box 5.2B. Rate: Third Schedule, 15 %. Input tax is the VAT paid on purchases by a taxable person for its business (SRC brochure).', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-return', null, null, null, null),
  ('SC', 'SC-P-15-CAP', 'Purchase of capital goods, standard rate 15 %, deductible', '{}'::jsonb, 'Goods of a capital nature bought locally for the business', 'percent', 15, 'purchase', 'domestic', date '2014-01-20', null, 'VAT return, line 5.3 — Input tax allowed as a credit on capital goods: the instructions ask for the total cost of capital goods imported or purchased for use in the business exclusive of VAT in box 5.3A and the VAT incurred in box 5.3B.', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-return', null, null, null, null),
  ('SC', 'SC-P-15-NC', 'Purchase, standard rate 15 %, input tax not allowed', '{}'::jsonb, 'A purchase on which input tax is not allowed as a credit — the VAT joins the cost', 'percent', 15, 'purchase', 'domestic', date '2014-01-20', null, 'VAT return, line 6 — Input tax not allowed as credit: the instructions ask for the total cost of the goods and services where the input tax is not allowed as a credit in box 6A; line 6 has no column B and does not enter the input tax credit of line 9. Which purchases the Act bars from credit is the preparer''s judgement; this pack does not list them.', 'S', null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-return', null, null, null, null),
  ('SC', 'SC-P-IMP', 'Purchase of imported goods, 15 % VAT paid at the border', '{}'::jsonb, 'Imported goods other than capital goods: the VAT is collected at the point of entry', 'percent', 15, 'purchase', 'import', date '2014-01-20', null, 'SRC brochure — VAT is collected at the point of entry at Customs on commercial and non-commercial importation. VAT return, line 5.1 — Input tax allowed as a credit on imported goods (excluding capital goods): the instructions ask for the customs value (CIF) plus taxes but excluding VAT in box 5.1A and the VAT incurred in box 5.1B. The VAT owed to the SRC sits on the import control account until paid.', null, null, 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-return', null, null, null, null),
  ('SC', 'SC-P-IMP-CAP', 'Purchase of imported capital goods, 15 % VAT paid at the border', '{}'::jsonb, 'Capital goods imported for the business', 'percent', 15, 'purchase', 'import', date '2014-01-20', null, 'VAT return, line 5.3 — capital goods imported or purchased for use in the business, box 5.3A the cost exclusive of VAT and box 5.3B the VAT incurred. The VAT owed at the border sits on the import control account until paid.', null, null, 160, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-return', null, null, null, null),
  ('SC', 'SC-S-15', 'Sale, standard rate 15 %', '{}'::jsonb, 'A taxable supply of goods or services made in Seychelles by a registered person, neither zero-rated nor exempt', 'percent', 15, 'sale', 'domestic', date '2014-01-20', null, 'Value Added Tax Act (Act 35 of 2010), Third Schedule as substituted by S.I. 4 of 2014 — the rate of VAT for the purposes of section 6 is 15 %; the SRC brochure adds that standard rated supplies are the goods and services that attract 15 %. VAT return, line 1 — Taxable supplies (Standard Rate @15 %), column A the value exclusive of VAT and column B the VAT.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-schedules', null, null, null, null),
  ('SC', 'SC-S-15-CAP', 'Sale of a capital asset, standard rate 15 %', '{}'::jsonb, 'The sale of an asset used in the business, taxable at the standard rate', 'percent', 15, 'sale', 'domestic', date '2014-01-20', null, 'VAT return, line 1.3 — On sale of capital asset: the instructions ask for the value excluding VAT in box 1.3A and the VAT collected in box 1.3B, and line 1 excludes the capital assets used in the business; line 4 adds 1.3B to the output tax. Rate: Third Schedule, 15 %.', 'S', null, 15, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-return', null, null, null, null),
  ('SC', 'SC-S-EX', 'Sale, exempt', '{}'::jsonb, 'A supply the First Schedule exempts — financial services, education, hospital and medical services, fresh bread, residential letting, the transfer of immovable property', 'percent', 0, 'sale', 'exempt', date '2014-01-20', null, 'VAT Act, First Schedule Part II as substituted by S.I. 4 of 2014 — exempt supplies include financial services of a bank or bureau de change (1(a)), education services (1(b)), insurance premiums of life, health, crop, livestock and marine insurance (1(d)), hospital, medical and dental services (1(e)), fresh bread (1(i)), public utility services (1(j)), the leasing of premises for residential dwelling (item 4) and the transfer of immovable property (item 5). An exempt supply carries no VAT and gives no right to deduct input tax (SRC brochure). VAT return, line 2 — Exempt Supplies.', 'E', null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-schedules', null, null, null, null),
  ('SC', 'SC-S-ZR', 'Sale, zero-rated (other than export)', '{}'::jsonb, 'A zero-rated supply made in Seychelles that is not an export — animal feed, duty-free shop sales, port services connected to international transport and the like', 'percent', 0, 'sale', 'domestic', date '2014-01-20', null, 'VAT Act, Second Schedule as substituted by S.I. 4 of 2014 — zero-rated supplies other than exports include item 1(m) goods supplied by a duty free shop, 1(n) animal feed and 1(o) port services connected to international transport. One tax code carries the whole list; which item applies is the preparer''s judgement. VAT return, line 1.2 — On zero-rated supplies (other than exports).', 'Z', null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-schedules', null, null, null, null),
  ('SC', 'SC-S-ZR-EXP', 'Sale, zero-rated (export)', '{}'::jsonb, 'Goods exported, or a service supplied to a person outside Seychelles, taxable at 0 %', 'percent', 0, 'sale', 'export', date '2014-01-20', null, 'VAT Act, Second Schedule as substituted by S.I. 4 of 2014, item 1(a) — goods manufactured for export, or entered for export under the Customs legislation and exported by the supplier, are zero-rated; items (f) and (g) — certain services to a person outside Seychelles; item (j) — international transport services. A zero-rated supply is a taxable supply at 0 % whose input tax stays deductible (SRC brochure). VAT return, line 1.1 — On exports.', 'G', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-schedules', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
