insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('SC', 'SC-VAT', 'VAT return', array['month']::declaration_period[], null, date '2014-01-20', null, 'SRC Value Added Tax Return — a monthly return lodged with the Business Activity Statement by the 21st of the month following the taxable period; a business registered voluntarily files and pays quarterly (Business Activity Statement form). A return with no operation is still lodged (BAS: a nil return must be lodged). The pack carries the lines a document writes into (1 to 6) and the totals of lines 4, 9 and 10 and 11; the declaration, the refund claim and the adjustments are the preparer''s.', true,'day_of_month_after_period'::filing_deadline_rule, 23, null, 'Revenue Law (Amendment) Act 2023, new section 3(1) — a monthly return is furnished on or before the 21st day of the month in which it is due when furnished in person, and on or before the 23rd when furnished through the SRC Tax Portal; section 3(2) — a large business furnishes through the Portal; new section 20 — the tax is paid by the 21st in person and by the 23rd through the Portal or by bank transfer, and a payment of SCR 50,000 or more goes through the Portal. The pack retains the 23rd, the date of the Portal; a taxpayer filing in person has the 21st, which the format cannot hold beside it. The VAT return itself and the Business Activity Statement print the 21st, which predates the 2023 Act. A quarterly voluntary filer is not modelled.', 'revenue-law-2023', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('SC', 'SC-VAT', '1', 'base', 'Line 1 — Taxable supplies at the standard rate — value (1A)', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 1, column A — the total sales at the standard rate exclusive of VAT, excluding capital assets used in the business.', 'vat-return'),
  ('SC', 'SC-VAT', '1', 'tax', 'Line 1 — Taxable supplies at the standard rate — VAT (1B)', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 1, column B — the VAT collected on the taxable supplies at 15 %.', 'vat-return'),
  ('SC', 'SC-VAT', '1a', 'base', 'Line 1.1 — On exports (1.1A)', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 1.1, column A — the total sales on exports. Column B is not printed for this line.', 'vat-return'),
  ('SC', 'SC-VAT', '1b', 'base', 'Line 1.2 — On zero-rated supplies other than exports (1.2A)', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 1.2, column A — the total sales on zero-rated supplies that are not exports.', 'vat-return'),
  ('SC', 'SC-VAT', '1c', 'base', 'Line 1.3 — On sale of capital asset — value (1.3A)', '{}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 1.3, column A — the total sale of capital assets excluding VAT.', 'vat-return'),
  ('SC', 'SC-VAT', '1c', 'tax', 'Line 1.3 — On sale of capital asset — VAT (1.3B)', '{}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 1.3, column B — the VAT collected on the sale of capital assets.', 'vat-return'),
  ('SC', 'SC-VAT', '2', 'base', 'Line 2 — Exempt supplies (2A)', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 2, column A — the total sales of exempt supplies.', 'vat-return'),
  ('SC', 'SC-VAT', '3', 'tax', 'Line 3 — Adjustments, output tax (3B)', '{}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 3, column B — adjustments, plus or minus (see the VAT guide). Declared and empty: an adjustment is a decision of the preparer, no tax code posts to it.', 'vat-return'),
  ('SC', 'SC-VAT', '4', 'total', 'Line 4 — Total output tax (4B)', '{}'::jsonb, 90, null, array['1:tax', '1c:tax', '3']::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 4 — total output tax = 1B + 1.3B + 3B.', 'vat-return'),
  ('SC', 'SC-VAT', '5a', 'base', 'Line 5.1 — Input tax on imported goods, excluding capital goods — value (5.1A)', '{}'::jsonb, 100, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 5.1, column A — the customs value (CIF) plus taxes but excluding VAT of the imported goods.', 'vat-return'),
  ('SC', 'SC-VAT', '5a', 'tax', 'Line 5.1 — Input tax on imported goods, excluding capital goods — VAT (5.1B)', '{}'::jsonb, 110, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 5.1, column B — the VAT incurred on imported goods.', 'vat-return'),
  ('SC', 'SC-VAT', '5b', 'base', 'Line 5.2 — Input tax on goods and services purchased locally — value (5.2A)', '{}'::jsonb, 120, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 5.2, column A — the cost of the goods and services purchased locally, exclusive of VAT.', 'vat-return'),
  ('SC', 'SC-VAT', '5b', 'tax', 'Line 5.2 — Input tax on goods and services purchased locally — VAT (5.2B)', '{}'::jsonb, 130, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 5.2, column B — the VAT incurred on goods and services purchased locally.', 'vat-return'),
  ('SC', 'SC-VAT', '5c', 'base', 'Line 5.3 — Input tax on capital goods — value (5.3A)', '{}'::jsonb, 140, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 5.3, column A — the cost of capital goods imported or purchased for use in the business, exclusive of VAT.', 'vat-return'),
  ('SC', 'SC-VAT', '5c', 'tax', 'Line 5.3 — Input tax on capital goods — VAT (5.3B)', '{}'::jsonb, 150, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 5.3, column B — the VAT incurred on capital goods.', 'vat-return'),
  ('SC', 'SC-VAT', '6', 'base', 'Line 6 — Input tax not allowed as credit — value (6A)', '{}'::jsonb, 160, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 6, column A — the cost of the goods and services where the input tax is not allowed as a credit. It does not enter line 9.', 'vat-return'),
  ('SC', 'SC-VAT', '7', 'tax', 'Line 7 — Adjustments, input tax (7B)', '{}'::jsonb, 170, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 7, column B — adjustments, plus or minus. Declared and empty, for the reason given at line 3.', 'vat-return'),
  ('SC', 'SC-VAT', '8', 'tax', 'Line 8 — VAT credit carried forward from the prior taxable period (8B)', '{}'::jsonb, 180, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 8, column B — the credit of the previous period. Declared and empty: a period-to-period carry is not a posting of the format; see the README.', 'vat-return'),
  ('SC', 'SC-VAT', '9', 'total', 'Line 9 — Input tax credit (9B)', '{}'::jsonb, 190, null, array['5a:tax', '5b:tax', '5c:tax', '7', '8']::text[], '{}'::text[], null, null, false, false, null, 'VAT return, line 9 — input tax credit = 5.1B + 5.2B + 5.3B + 7B + 8B.', 'vat-return'),
  ('SC', 'SC-VAT', '10', 'total', 'Lines 10 and 11 — VAT payable (positive) or VAT credit (negative)', '{}'::jsonb, 200, null, array['4']::text[], array['9']::text[], null, null, false, false, null, 'VAT return, line 10 — VAT payable where the total output tax (4B) exceeds the input tax credit (9B), entered in box 10A; line 11 — VAT credit where 9B exceeds 4B, entered in box 11B. The two lines are one signed figure here: positive is payable, negative is the credit, which can be refunded or carried forward (claim for refund section of the form).', 'vat-return')
